export class AudioAnalyser {
  constructor(fftSize = 256) {
    this.fftSize = fftSize;
    this.audioContext = null;
    this.analyser = null;
    this.source = null;
    this.frequencyData = new Uint8Array(fftSize / 2);
    this.connected = false;
  }

  connectToElement(audioElement) {
    if (!this.audioContext) {
      this.audioContext = new (window.AudioContext || window.webkitAudioContext)();
    }

    if (this.audioContext.state === 'suspended') {
      this.audioContext.resume();
    }

    // Only create one MediaElementSource per audio element — calling twice throws
    if (this.source) return;

    this.source = this.audioContext.createMediaElementSource(audioElement);
    this.analyser = this.audioContext.createAnalyser();
    this.analyser.fftSize = this.fftSize;
    this.analyser.smoothingTimeConstant = 0.8;
    this.analyser.minDecibels = -90;
    this.analyser.maxDecibels = -10;

    this.source.connect(this.analyser);
    this.analyser.connect(this.audioContext.destination);

    this.frequencyData = new Uint8Array(this.analyser.frequencyBinCount);
    this.connected = true;
  }

  getFrequencyData() {
    if (!this.connected || !this.analyser) return this.frequencyData;
    this.analyser.getByteFrequencyData(this.frequencyData);
    return this.frequencyData;
  }

  dispose() {
    if (this.source) this.source.disconnect();
    if (this.analyser) this.analyser.disconnect();
    if (this.audioContext) this.audioContext.close();
    this.connected = false;
  }
}
