// Simple preview-URL player using a reusable <audio> element.
// CORS: crossOrigin must be set before src so AnalyserNode gets frequency data.

let audioElement = null;

export function getAudioElement() {
  if (!audioElement) {
    audioElement = document.createElement('audio');
    audioElement.crossOrigin = 'anonymous';
  }
  return audioElement;
}

export function playPreview(previewUrl) {
  const audio = getAudioElement();
  audio.pause();
  audio.src = previewUrl;
  return audio.play().catch(err => {
    // AbortError is expected when a new load interrupts a pending play()
    if (err.name === 'AbortError') return;
    throw err;
  });
}

export function pause() {
  if (audioElement) audioElement.pause();
}

export function resume() {
  if (audioElement) return audioElement.play().catch(err => {
    if (err.name === 'AbortError') return;
    throw err;
  });
}
