import { useState, useRef, useEffect, useCallback } from 'react';
import { searchDnBTracks } from '../services/music/musicService';
import { getAudioElement, playPreview, pause, resume } from '../services/music/musicPlayer';
import { AudioAnalyser } from '../services/audio/audioAnalyser';
import { FrequencyTexture } from '../services/audio/frequencyTexture';

export function useMusic() {
  const [playing, setPlaying] = useState(false);
  const [currentTrack, setCurrentTrack] = useState(null);
  const [trackQueue, setTrackQueue] = useState([]);

  const analyserRef = useRef(null);
  const freqTextureRef = useRef(null);
  const frequencyTextureRef = useRef(null); // the THREE.DataTexture itself
  const audioReactiveRef = useRef(0.0);
  const trackCacheRef = useRef({});
  const analyserConnectedRef = useRef(false);
  const lastFetchedCode = useRef(null);

  // Create audio pipeline instances on mount
  useEffect(() => {
    analyserRef.current = new AudioAnalyser();
    freqTextureRef.current = new FrequencyTexture();
    frequencyTextureRef.current = freqTextureRef.current.getTexture();

    return () => {
      analyserRef.current?.dispose();
      freqTextureRef.current?.dispose();
    };
  }, []);

  // When audio ends, play next track in queue
  useEffect(() => {
    const audio = getAudioElement();
    const handleEnded = () => {
      const currentIdx = trackQueue.findIndex(t => t.id === currentTrack?.id);
      const next = trackQueue[currentIdx + 1];
      if (next && next.preview_url) {
        playPreview(next.preview_url);
        setCurrentTrack(next);
      } else {
        setPlaying(false);
      }
    };
    audio.addEventListener('ended', handleEnded);
    return () => audio.removeEventListener('ended', handleEnded);
  }, [trackQueue, currentTrack]);

  const fetchTracksForMarket = useCallback(async (countryCode) => {
    // Skip if we already loaded this country
    if (lastFetchedCode.current === countryCode) return;
    lastFetchedCode.current = countryCode;

    // Use cached results if available
    if (trackCacheRef.current[countryCode]) {
      const cached = trackCacheRef.current[countryCode];
      setTrackQueue(cached);
      if (playing && cached.length > 0 && cached[0].preview_url) {
        playPreview(cached[0].preview_url);
        setCurrentTrack(cached[0]);
      }
      return;
    }

    try {
      const tracks = await searchDnBTracks(countryCode);
      // Another country may have been requested while we were fetching
      if (lastFetchedCode.current !== countryCode) return;
      trackCacheRef.current[countryCode] = tracks;
      setTrackQueue(tracks);

      if (playing && tracks.length > 0 && tracks[0].preview_url) {
        playPreview(tracks[0].preview_url);
        setCurrentTrack(tracks[0]);
      }
    } catch (err) {
      console.error('Failed to fetch tracks:', err);
    }
  }, [playing]);

  const connectAnalyser = useCallback(() => {
    if (analyserConnectedRef.current) return;
    const audio = getAudioElement();
    analyserRef.current.connectToElement(audio);
    analyserConnectedRef.current = true;
  }, []);

  const togglePlayPause = useCallback(() => {
    if (playing) {
      pause();
      setPlaying(false);
    } else {
      connectAnalyser();
      if (currentTrack?.preview_url) {
        resume();
      } else if (trackQueue.length > 0 && trackQueue[0].preview_url) {
        playPreview(trackQueue[0].preview_url);
        setCurrentTrack(trackQueue[0]);
      }
      setPlaying(true);
    }
  }, [playing, currentTrack, trackQueue, connectAnalyser]);

  // Called every frame to pump frequency data into the texture
  const updateFrequencyData = useCallback(() => {
    if (!analyserRef.current || !freqTextureRef.current) return;
    const data = analyserRef.current.getFrequencyData();
    freqTextureRef.current.update(data);
  }, []);

  return {
    isPlaying: playing,
    currentTrack,
    togglePlayPause,
    fetchTracksForMarket,
    updateFrequencyData,
    frequencyTextureRef,
    audioReactiveRef,
    analyserConnected: analyserConnectedRef
  };
}
